import json,urllib.request
B="https://portal.sqd.dev/datasets/base-mainnet"
def post(q):
    r=urllib.request.Request(B+"/stream",data=json.dumps(q).encode(),headers={"Content-Type":"application/json","User-Agent":"curl/8"})
